examples.template:
MonarchAiStarterPrompts(
    [
        MonarchAiStarterPrompt(id: {{prompts.0.id}}, title: {{prompts.0.title}}, prompt: {{prompts.0.prompt}}),
        MonarchAiStarterPrompt(id: {{prompts.1.id}}, title: {{prompts.1.title}}, prompt: {{prompts.1.prompt}}),
        MonarchAiStarterPrompt(id: {{prompts.2.id}}, title: {{prompts.2.title}}, prompt: {{prompts.2.prompt}}),
        MonarchAiStarterPrompt(id: {{prompts.3.id}}, title: {{prompts.3.title}}, prompt: {{prompts.3.prompt}}),
    ],
    layout: {{layout|case}}
) { _ in }

examples.code:
MonarchAiStarterPrompts(
    [
        MonarchAiStarterPrompt(id: "summary", title: "Summarise a document", prompt: "Summarise the open document in five bullet points."),
        MonarchAiStarterPrompt(id: "reply", title: "Draft a reply", prompt: "Draft a short, friendly reply to the latest message."),
        MonarchAiStarterPrompt(id: "plan", title: "Plan the week", prompt: "Turn my open tasks into a plan for this week."),
        MonarchAiStarterPrompt(id: "explain", title: "Explain a chart", prompt: "Explain what the chart on this page shows and what stands out."),
    ],
    layout: .grid
) { _ in }

MonarchAiStarterPrompts(
    [
        MonarchAiStarterPrompt(id: "plan", title: "Plan my week", prompt: "Turn my open tasks into a plan."),
        MonarchAiStarterPrompt(id: "brief", title: "Brief me", prompt: "What changed since yesterday?"),
    ],
    layout: .list,
    hidesPrompt: true
) { starter in
    draft = starter.prompt
}
